    case("J-N5", "no_evidence", "Which company supplies the Harbor GPU host hardware?", abstain=True, distractors=["document:doc-arch", "meeting:mt-weekly#57"], forbidden=[r"\b(?:nvidia|dell|supermicro|lenovo|aws|azure|google cloud)\b"]),
    case("J-N6", "no_evidence", "Which time zone does Priya work in?", abstain=True, distractors=["memory:mem-priya-pref", "note:note-actions"], forbidden=[r"\b(?:utc|gmt|est|pst|cet|sgt|pacific time|eastern time|central time)\b"]),
    # -- evidence about the wrong entity --
    case("J-W1", "wrong_entity", "Who owns the Beacon Analytics account relationship?", abstain=True, distractors=["document:doc-vendor", "memory:mem-quill-owner"], forbidden=[r"\b(?:priya|tomas|dana)\b[^.]{0,40}\bowns?\b[^.]{0,30}beacon"]),
    case("J-W2", "wrong_entity", "Which model does the Quill queue run?", abstain=True, distractors=["document:doc-arch", "memory:mem-model-current"], forbidden=[r"quill[^.]{0,40}\bruns?\b[^.]{0,20}falcon"]),
    case("J-W3", "wrong_entity", "What is the support line number for Harbor?", abstain=True, distractors=["document:doc-vendor", "document:doc-arch"], forbidden=[r"harbor(?:'s)? support (?:line|number)[^.]{0,15}\b(?:is|:)\s*555"]),
    case("J-W4", "wrong_entity", "What is Priya's role at Harbor?", abstain=True, distractors=["memory:mem-priya-pref", "meeting:mt-planning#0"], forbidden=[r"priya[^.]{0,30}\b(?:is|as)\b[^.]{0,20}\b(?:product manager|project manager|director|head of|lead)\b"]),
    case("J-W5", "wrong_entity", "How long should I watch the dashboard after a Harbor deploy?", abstain=True, distractors=["document:doc-lantern-runbook", "document:doc-arch"], forbidden=[r"harbor[^.]{0,40}\b(?:ten|10)\s*minutes"]),
    case("J-W6", "wrong_entity", "Who audits the Lantern logs?", abstain=True, distractors=["task:task-dana", "note:note-lantern"], forbidden=[r"\bdana\b[^.]{0,40}\baudit[^.]{0,20}lantern", r"lantern[^.]{0,40}\bdana\b[^.]{0,20}\baudit"]),
