    case("J-P1", "partial_evidence", "Who signed off the security review for the Harbor release and how long did the review take?", gold=["meeting:mt-weekly#71", "memory:mem-dana-security"], required=[[r"dana"]], forbidden=[r"\b\d+\s*(?:minutes?|hours?|days?|weeks?)\b[^.]{0,20}\breview|review[^.]{0,30}\btook\b[^.]{0,15}\b\d+"], note="no duration is recorded"),
    case("J-P2", "partial_evidence", "How large is the GPU host budget and through when is it approved?", gold=["meeting:mt-weekly#57"], required=[[r"december"]], forbidden=[r"[$€£]\s?\d", r"\b\d[\d,]*\s?(?:dollars|usd|euros)\b"], note="no amount is recorded"),
