    case("J-C3", "conflict", "Compare what the Lantern runbook and my memory give as the rollback deadline.", gold=["document:doc-lantern-runbook", "memory:mem-rollback-window"], required=[[r"\b30\b", r"thirty"], [r"\b60\b", r"sixty"]], conflict=True),
    case("J-C4", "conflict", "Do any of my records disagree about Harbor's retry limit?", gold=["document:doc-arch", "memory:mem-retry-conflict"], required=[[r"\b5\b", r"five"], [r"\b10\b", r"\bten\b"]], conflict=True),
