    # -- temporal / supersession --
    case("J-T1", "supersession", "Which Falcon model was Harbor's default in March?", temporal="include_historical", gold=["memory:mem-model-old", "memory:mem-model-current"], required=[[r"falcon-?1b"]], forbidden=[r"\bfalcon-?7b\b[^.]{0,30}\bin march"]),
    case("J-T2", "supersession", "Has the 30-minute Lantern rollback figure been revised?", abstain=True, distractors=["document:doc-lantern-runbook", "memory:mem-rollback-window"], forbidden=[SUPERSEDED, r"\b(?:was|has been) (?:revised|updated|changed)\b"], note="the records do not order the two figures"),
    case("J-T3", "supersession", "Which of Harbor's architecture documents is the older one?", temporal="include_historical", gold=["document:doc-arch-v1", "document:doc-arch"], required=[[r"archived", r"\bv1\b", r"older", r"first version"]]),
    case("J-T4", "supersession", "Is the three-retry limit still in force for Harbor?", temporal="include_historical", gold=["document:doc-arch", "document:doc-arch-v1", "meeting:mt-planning#6"], required=[[r"\b5\b", r"five"]], forbidden=[r"^\s*yes\b"]),
    case("J-T5", "supersession", "Which date was the Lantern launch review originally set for?", gold=["memory:mem-lantern-slip", "meeting:mt-lantern#1"], required=[[r"14th", r"fourteenth"]], forbidden=[r"\boriginally (?:scheduled|planned|set) (?:for|on)\s+(?:the\s+)?\d", r"\bfrom the \d+(?:st|nd|rd|th)? to the 14th\b"], note="only the new date, the 14th, is recorded"),
    # -- mixed: some parts supported, one part unknown --
